def parse_log(text):
    lines = text.splitlines()
    parsed_logs = []
    bad_lines = []

    for i, line in enumerate(lines):
        if line.strip() == "":
            continue
        try:
            # Assuming log lines are in JSON format
            parsed_logs.append(json.loads(line))
        except json.JSONDecodeError:
            bad_lines.append(i + 1)

    return parsed_logs, bad_lines

