def top_paths(entries, n=3):
    from collections import Counter
    from urllib.parse import urlparse

    path_counts = Counter()

    for entry in entries:
        parsed_url = urlparse(entry['path'])
        path = parsed_url.path
        path_counts[path] += 1

    return path_counts.most_common(n)

