def to_html(text):
    import re

    def convert_link(match):
        url = match.group(2)
        text = match.group(1)
        return f'<a href="{url.replace(\'"\', \'&quot;\')}">{text}</a>'

    link_pattern = re.compile(r'\[(.*?)\]\((.*?)\)')
    return link_pattern.sub(convert_link, text)

